    [InlineData(LoyaltyTier.Gold, 20_000, 18_000)]   // 10%
    [InlineData(LoyaltyTier.Platinum, 4_999, 4_550)] // 9%: 449.91 -> 449
    [InlineData(LoyaltyTier.Platinum, 5_000, 4_500)] // 10%
    [InlineData(LoyaltyTier.Platinum, 20_000, 18_000)] // capped at 10%
    [InlineData(LoyaltyTier.Green, 0, 0)]
    [InlineData(LoyaltyTier.Green, 19, 19)]          // 0.95 -> 0 off
    [InlineData(LoyaltyTier.Gold, 99, 93)]           // 6.93 -> 6 off
    public void CustomersPayTheApprovedLoyaltyTotal(LoyaltyTier loyaltyTier, int subtotalCents, int expectedPayableCents)
    {
        var useCase = new CalculatePayableTotal();

        Assert.Equal(expectedPayableCents, useCase.For(subtotalCents, loyaltyTier));
    }
}
